    Lore const* Table(Kind kind, size_t& count)
    {
        switch (kind)
        {
            case Kind::Weapon: count = std::size(kWeapons); return kWeapons;
            case Kind::Attachment: count = std::size(kAttachments); return kAttachments;
            case Kind::Camo: count = std::size(kCamos); return kCamos;
            case Kind::Perk: count = std::size(kPerks); return kPerks;
            case Kind::Killstreak: count = std::size(kKillstreaks); return kKillstreaks;
            case Kind::Count: break;
        }
        count = 0;
        return nullptr;
    }
